                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == background and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            if not touches_edge:
                for y, x in cells:
                    out[y][x] = 4
    return out


